  test('FR-HOF-11: failed submit retains the draft and retries its ID', () async {
    final repository = _FakeHandoffRepository();
    final form = HandoffFormCubit(
      handoffRepository: repository,
      spaceId: 'space-synthetic-1',
      channelId: 'channel-synthetic-1',
      currentUserId: _sender.id,
    );
    addTearDown(form.close);
    form.setAssignedDoctor(_receiver);
    form.setShiftDate(DateTime.utc(2026, 10, 10));
    form.setShiftSummary('Synthetic shift summary');
    form.setPatients(const [_patient]);

    final first = await form.submit();
    expect(first, isNull);
    expect(form.state.handoffId, 'handoff-synthetic-1');
    expect(form.state.error, 'Synthetic submit failure');
    expect(form.state.isSaving, isFalse);
    expect(form.state.shiftSummary, 'Synthetic shift summary');
    expect(form.state.patients, const [_patient]);
    expect(repository.createCalls, 1);
    expect(repository.updateCalls, 0);
    expect(repository.submitCalls, 1);
    expect(repository.savedPatients, const [_patient]);

    final retried = await form.submit();
    expect(retried?.status, HandoffStatus.submitted);
    expect(retried?.id, 'handoff-synthetic-1');
    expect(form.state.error, isNull);
    expect(repository.createCalls, 1, reason: 'Retry must not create another draft');
    expect(repository.updateCalls, 1);
    expect(repository.updatedIds, ['handoff-synthetic-1']);
    expect(repository.submittedIds, ['handoff-synthetic-1', 'handoff-synthetic-1']);
    expect(repository.savedSummary, 'Synthetic shift summary');
    expect(repository.savedPatients, const [_patient]);
  });
}

  testWidgets('FR-HOF-12: local-day labels preserve server status [NEEDS_DECISION Q12]',
      (tester) async {
    final started = DateTime.now();
    final today = DateTime(started.year, started.month, started.day);
    final dates = <String, DateTime>{
      'yesterday': today.subtract(const Duration(days: 1)),
      'today': today,
      'tomorrow': today.add(const Duration(days: 1)),
    };
    final handoffs = <HandoffModel>[
      for (final entry in dates.entries)
        _handoff('${entry.key}-submitted', entry.value, HandoffStatus.submitted),
      for (final entry in dates.entries)
        _handoff('${entry.key}-acknowledged', entry.value,
            HandoffStatus.acknowledged),
    ];
    expect(handoffs, hasLength(6));
    for (final handoff in handoffs) {
      final originalStatus = handoff.status;
      final originalDate = handoff.shiftDate;
      final label = handoff.lifecycleLabel;
      expect(label, isNotEmpty);
      expect(handoff.status, originalStatus,
          reason: 'Reading a client label cannot transition backend status');
      expect(handoff.shiftDate, originalDate);
      if (handoff.id.startsWith('yesterday')) {
        expect(handoff.isShiftPast, isTrue);
      } else {
        expect(handoff.isShiftPast, isFalse);
      }
      await tester.pumpWidget(MaterialApp(home: Scaffold(body: HandoffCard(
        handoff: handoff, onTap: () {},
      ))));
      final displayed = label == 'Completed' ? 'Done' : label;
      expect(find.text(displayed), findsOneWidget,
          reason: 'The card must present the lifecycle calculated by its model');
      expect(handoff.status, originalStatus);
      expect(handoff.shiftDate, originalDate);
    }
    expect(DateTime.now().day, started.day,
        reason: 'Direct DateTime.now() source requires a run within one local day');
  });
}

  testWidgets('FR-HOF-13: patient editor validates, cancels and saves selected patient',
      (tester) async {
    tester.view.physicalSize = const Size(900, 1600);
    tester.view.devicePixelRatio = 1;
    addTearDown(() {
      tester.view.resetPhysicalSize();
      tester.view.resetDevicePixelRatio();
    });
    const first = HandoffPatientModel(
      id: 'patient-synthetic-a', bedNumber: 'A-01',
      clinicalAlias: 'Synthetic Patient A',
      pendingTasks: ['Review CBC', 'Check ECG'],
    );
    const second = HandoffPatientModel(
      id: 'patient-synthetic-b', bedNumber: 'B-02',
      clinicalAlias: 'Synthetic Patient B',
      pendingTasks: ['Review imaging'],
    );
    final patients = ValueNotifier<List<HandoffPatientModel>>([first, second]);
    addTearDown(patients.dispose);
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: Builder(
      builder: (context) => Column(children: [
        FilledButton(
          onPressed: () async {
            final updated = await PatientEditorSheet.show(context,
                initial: patients.value.first);
            if (updated != null) {
              patients.value = [updated, patients.value[1]];
            }
          },
          child: const Text('Edit selected patient'),
        ),
        ValueListenableBuilder<List<HandoffPatientModel>>(
          valueListenable: patients,
          builder: (_, value, __) => Text(
            '${value[0].pendingTasks.join(', ')} | ${value[0].isFlagged} | '
            '${value[1].pendingTasks.join(', ')}',
          ),
        ),
      ]),
    ))));
    await tester.tap(find.text('Edit selected patient'));
    await tester.pumpAndSettle();
    expect(find.text('Edit patient'), findsOneWidget);
    final bed = find.widgetWithText(TextField, 'Bed number');
    final tasks = find.widgetWithText(TextField, 'Pending tasks');
    await tester.enterText(bed, '');
    await tester.ensureVisible(find.text('Save'));
    await tester.tap(find.text('Save'));
    await tester.pump();
    expect(find.text('Bed number and clinical alias required'), findsOneWidget);
    expect(find.text('Edit patient'), findsOneWidget,
        reason: 'Validation must happen before the sheet submits');
    expect(patients.value, [first, second]);

    await tester.enterText(bed, 'A-01');
    await tester.enterText(tasks, 'Review CBC\nCheck potassium');
    await tester.tap(find.text('High priority'));
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(patients.value, [first, second],
        reason: 'Cancel must not update the draft patient list');

    await tester.tap(find.text('Edit selected patient'));
    await tester.pumpAndSettle();
    await tester.enterText(tasks, 'Review CBC\nCheck potassium');
    await tester.tap(find.text('High priority'));
    final attachmentControlVisible =
        find.textContaining('Attachment').evaluate().isNotEmpty ||
        find.byIcon(Icons.attach_file).evaluate().isNotEmpty;
    await tester.ensureVisible(find.text('Save'));
    await tester.tap(find.text('Save'));
    await tester.pumpAndSettle();
    expect(patients.value.first.id, first.id);
    expect(patients.value.first.pendingTasks, ['Review CBC', 'Check potassium']);
    expect(patients.value.first.isFlagged, isTrue);
    expect(patients.value[1], second,
        reason: 'Saving one patient cannot mutate another patient');
    expect(attachmentControlVisible, isTrue,
        reason: 'Catalog requires adding and removing a patient attachment');
  });
}

  test('FR-HOME-01 widget order and visibility survive reload, merge and reset', () async {
    SharedPreferences.setMockInitialValues({});
    final storage = await SharedPreferences.getInstance();
    final service = DashboardPreferencesService(preferences: storage);
    final defaults = await service.load();
    final custom = [
      defaults.firstWhere((item) => item.id == DashboardWidgetId.quickActions).copyWith(isVisible: false),
      defaults.firstWhere((item) => item.id == DashboardWidgetId.emergency),
    ];
    await service.save(custom);

    final reopened = DashboardPreferencesService(preferences: storage);
    final restored = await reopened.load();
    expect(restored.take(2).map((item) => item.id).toList(), [
      DashboardWidgetId.quickActions, DashboardWidgetId.emergency,
    ]);
    expect(restored.first.isVisible, isFalse);
    expect(restored.map((item) => item.id).toSet(), DashboardWidgetId.values.toSet());

    await reopened.reset();
    final reset = await DashboardPreferencesService(preferences: storage).load();
    expect(reset.map((item) => item.id).toList(),
        DashboardPreferencesService.defaultPreferences.map((item) => item.id).toList());
    expect(reset.firstWhere((item) => item.id == DashboardWidgetId.quickActions).isVisible, isTrue);

    await storage.setString('medcollab_dashboard_widgets_v4', '{corrupt');
    final recovered = await DashboardPreferencesService(preferences: storage).load();
    expect(recovered.map((item) => item.id).toList(),
        DashboardPreferencesService.defaultPreferences.map((item) => item.id).toList());
  });
}

testWidgets('FR-HOME-02: assigned, shift and task cards follow refreshed handoffs', (tester) async {
  SharedPreferences.setMockInitialValues({});
  final storage = await SharedPreferences.getInstance();
  final handoffs = _Handoffs();
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day, 12);
  handoffs.server = [
    _handoff('assigned', _doctorB, HandoffStatus.submitted, today),
    _handoff('other-doctor', _doctorC, HandoffStatus.submitted, today),
    _handoff('draft', _doctorB, HandoffStatus.draft, today),
  ];
  final dashboard = HomeDashboardCubit(
    spaceRepository: _Spaces(),
    handoffRepository: handoffs,
    channelRepository: _Channels(),
    notificationRepository: _Notifications(),
    recentItemsService: RecentItemsService(prefs: storage),
    bookmarkService: BookmarkService(prefs: storage),
    dashboardPreferencesService: DashboardPreferencesService(preferences: storage),
    currentUserId: _doctorB.id,
  );
  addTearDown(dashboard.close);
  await dashboard.load();
  expect(dashboard.state.isLoading, isFalse);
  expect(dashboard.state.error, isNull);
  expect(dashboard.state.assignedHandoffs.map((h) => h.id), ['assigned']);
  expect(dashboard.state.todayHandoffs.map((h) => h.id), ['assigned']);
  expect(dashboard.state.pendingHandoffs, 1);
  expect(dashboard.state.pendingTaskCount, 1);
  Future<void> renderCards() async {
    // Flutter 3.29.3's diagnostic-tree renderer can itself throw while
    // formatting a failed paint. Capture the original exception before that
    // formatting step, then explicitly fail; never suppress a render defect.
    final previousHandler = FlutterError.onError;
    final renderErrors = <String>[];
    FlutterError.onError = (details) {
      renderErrors.add('${details.exception}\n${details.stack}');
    };
    try {
      await tester.pumpWidget(MaterialApp(home: Scaffold(body: SingleChildScrollView(
        child: Column(children: [
          TodayShiftWidget(handoffs: dashboard.state.todayHandoffs, onOpenHandoffs: () {}),
          AssignedHandoffsWidget(handoffs: dashboard.state.assignedHandoffs),
          PendingTasksWidget(state: dashboard.state),
        ]),
      ))));
    } finally {
      FlutterError.onError = previousHandler;
    }
    if (renderErrors.isNotEmpty) {
      throw TestFailure('Application card rendering failed:\n${renderErrors.join('\n')}');
    }
  }
  await renderCards();
  expect(find.text('Synthetic shift assigned'), findsOneWidget);
  expect(find.text('Handoffs awaiting action'), findsOneWidget);
  expect(find.text('No pending handoffs'), findsNothing);

  handoffs.server = [
    _handoff('assigned', _doctorB, HandoffStatus.acknowledged, today),
    _handoff('other-doctor', _doctorC, HandoffStatus.submitted, today),
  ];
  await dashboard.load(silent: true);
  expect(dashboard.state.assignedHandoffs, isEmpty);
  expect(dashboard.state.todayHandoffs, isEmpty);
  expect(dashboard.state.pendingHandoffs, 0);
  expect(dashboard.state.pendingTaskCount, 0);
  await renderCards();
  expect(find.text('No shift assignment for today'), findsOneWidget);
  expect(find.text('No pending handoffs'), findsOneWidget);
  expect(find.text('All caught up'), findsOneWidget);

  handoffs.server = [
    _handoff('assigned', _doctorC, HandoffStatus.submitted, today),
  ];
  await dashboard.load(silent: true);
  expect(dashboard.state.assignedHandoffs, isEmpty,
      reason: 'Reassigned handoff belongs to the new assignee');
  expect(dashboard.state.todayHandoffs, isEmpty);
  expect(dashboard.state.pendingTaskCount, 0);
  expect(handoffs.reads, greaterThanOrEqualTo(3));
}, timeout: const Timeout(Duration(seconds: 45)));

  testWidgets('FR-HOME-03: announcements, emergency, partial failure and retry',
      (tester) async {
    SharedPreferences.setMockInitialValues({});
    final prefs = await SharedPreferences.getInstance();
    final spaces = _Spaces();
    final channels = _Channels();
    final dashboard = HomeDashboardCubit(
      spaceRepository: spaces,
      handoffRepository: _Handoffs(),
      channelRepository: channels,
      notificationRepository: _Notifications(),
      recentItemsService: RecentItemsService(prefs: prefs),
      bookmarkService: BookmarkService(prefs: prefs),
      dashboardPreferencesService:
          DashboardPreferencesService(preferences: prefs),
      currentUserId: _doctorB.id,
    );
    addTearDown(dashboard.close);
    await dashboard.load();
    expect(dashboard.state.error, isNull);
    expect(dashboard.state.spaces, isEmpty);
    expect(dashboard.state.hospitalAnnouncements, isEmpty);
    expect(dashboard.state.departmentAnnouncements, isEmpty);
    await tester.pumpWidget(const MaterialApp(home: Scaffold(
      body: WorkspaceAnnouncementsWidget(
        title: 'Hospital announcements', announcements: [],
        emptyMessage: 'Announcements will appear here.',
      ),
    )));
    expect(find.text('No announcements'), findsOneWidget);

    spaces.server = const [
      SpaceModel(id: 'hospital-synthetic', name: 'Synthetic Hospital',
        type: SpaceType.hospital, channels: [
          ChannelModel(id: 'hospital-news', name: 'News',
            type: ChannelType.announcements,
            lastMessage: LastMessagePreview(text: 'Hospital announcement')),
          ChannelModel(id: 'hospital-emergency', name: 'Emergency',
            type: ChannelType.emergency,
            lastMessage: LastMessagePreview(text: 'Emergency discussion')),
        ]),
      SpaceModel(id: 'department-synthetic', name: 'Synthetic Department',
        type: SpaceType.department, channels: [
          ChannelModel(id: 'department-news', name: 'Department news',
            type: ChannelType.announcements,
            lastMessage: LastMessagePreview(text: 'Department announcement')),
        ]),
    ];
    channels.fail = true;
    await dashboard.load();
    expect(dashboard.state.error, isNull,
        reason: 'DM-only failure must not hide available workspace data');
    expect(dashboard.state.recentDms, isEmpty);
    expect(dashboard.state.hospitalAnnouncements.map((a) => a.channelId),
        ['hospital-news']);
    expect(dashboard.state.departmentAnnouncements.map((a) => a.channelId),
        ['department-news']);
    expect(dashboard.state.patientDiscussions.map((d) => d.channelId),
        ['hospital-emergency']);

    final router = GoRouter(initialLocation: '/home-test', routes: [
      GoRoute(path: '/home-test', builder: (_, __) => Scaffold(body: ListView(
        children: [
          WorkspaceAnnouncementsWidget(title: 'Hospital announcements',
            announcements: dashboard.state.hospitalAnnouncements,
            emptyMessage: 'None'),
          WorkspaceAnnouncementsWidget(title: 'Department announcements',
            announcements: dashboard.state.departmentAnnouncements,
            emptyMessage: 'None'),
          PatientDiscussionsWidget(
            discussions: dashboard.state.patientDiscussions),
        ],
      ))),
      GoRoute(path: '/spaces/:spaceId/channels/:channelId',
        builder: (_, state) => Scaffold(body: Text(
          'Opened ${state.pathParameters['spaceId']}/${state.pathParameters['channelId']}',
        ))),
    ]);
    addTearDown(router.dispose);
    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
    await tester.pumpAndSettle();
    expect(find.text('Hospital announcement'), findsOneWidget);
    expect(find.text('Department announcement'), findsOneWidget);
    await tester.tap(find.text('Hospital announcement'));
    await tester.pumpAndSettle();
    expect(find.text('Opened hospital-synthetic/hospital-news'), findsOneWidget);
    router.go('/home-test');
    await tester.pumpAndSettle();
    await tester.ensureVisible(find.text('Emergency discussion'));
    await tester.tap(find.text('Emergency discussion'));
    await tester.pumpAndSettle();
    expect(find.text('Opened hospital-synthetic/hospital-emergency'),
        findsOneWidget);

    spaces.fail = true;
    await dashboard.load();
    expect(dashboard.state.isLoading, isFalse);
    expect(dashboard.state.error, 'Synthetic workspace failure');
    spaces.fail = false;
    await dashboard.load();
    expect(dashboard.state.isLoading, isFalse);
    expect(dashboard.state.error, isNull);
    expect(dashboard.state.hospitalAnnouncements.single.channelId,
        'hospital-news');
    expect(dashboard.state.departmentAnnouncements.single.channelId,
        'department-news');
  });
}

testWidgets('FR-LINK-01: forwarding retains payload and sheet on failure', (tester) async {
  final messages = FakeMessageRepository();
  final deps = AppDependencies.instance;
  deps.messageRepository = messages;
  const source = MessageModel(
    id: 'source-message',
    channelId: 'source-channel',
    sender: UserModel(id: 'doctor-a', name: 'Doctor A'),
    content: MessageContent(
      text: 'Synthetic shift note',
      mediaUrl: 'https://synthetic.invalid/file.jpg',
    ),
  );
  final sent = <String>[];
  var fail = true;
  messages.onSendText = (text, replyTo) async {
    sent.add(text);
    if (fail) {
      fail = false;
      throw const ServerException('Synthetic forward failure');
    }
    return const MessageModel(
      id: 'forwarded-message',
      channelId: 'destination-group',
      sender: UserModel(id: 'doctor-b', name: 'Doctor B'),
      content: MessageContent(text: 'Forwarded'),
    );
  };
  await tester.pumpWidget(MaterialApp(home: Scaffold(body: Builder(
    builder: (context) => TextButton(
      onPressed: () => showForwardMessageSheet(
        context, message: source, sourceChannelId: 'source-channel',
      ),
      child: const Text('Forward source'),
    ),
  ))));
  await tester.tap(find.text('Forward source'));
  await tester.pumpAndSettle();
  expect(find.text('Doctor Ben'), findsOneWidget);
  expect(find.text('#Team group'), findsOneWidget);
  expect(find.text('#Source channel'), findsNothing,
      reason: 'The source must not be a forwarding target');

  await tester.tap(find.text('#Team group'));
  await tester.pumpAndSettle();
  expect(sent.length, 1);
  expect(find.text('Forward message'), findsOneWidget,
      reason: 'A failed send keeps the target sheet open for retry');
  expect(find.text('Synthetic forward failure'), findsOneWidget);
  await tester.tap(find.text('#Team group'));
  await tester.pumpAndSettle();
  expect(sent.length, 2);
  expect(messages.textSendCount, 2);
  expect(find.text('Forward message'), findsNothing);
  expect(messages.sentChannelIds, ['destination-group', 'destination-group']);
  expect(sent.last, contains('Forwarded from Doctor A'));
  expect(sent.last, contains('vocle://c/source-channel/m/source-message'));
  expect(sent.last, contains('Synthetic shift note'));
  expect(sent.last, contains('https://synthetic.invalid/file.jpg'));
  expect(sent.first, sent.last,
      reason: 'Retry must preserve exact source attribution and media URL');
});

  testWidgets('FR-LINK-02: copy exact message link [NEEDS_DECISION Q13]',
      (tester) async {
    String? copied;
    tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
      SystemChannels.platform, (call) async {
        if (call.method == 'Clipboard.setData') {
          copied = (call.arguments as Map)['text'] as String?;
        }
        return null;
      },
    );
    addTearDown(() => tester.binding.defaultBinaryMessenger
        .setMockMethodCallHandler(SystemChannels.platform, null));
    const source = MessageModel(
      id: 'source-message', channelId: 'source-channel',
      sender: UserModel(id: 'doctor-a', name: 'Doctor A'),
      content: MessageContent(text: 'Synthetic shift note'),
    );
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: Builder(
      builder: (context) => TextButton(
        onPressed: () => showForwardMessageSheet(context,
            message: source, sourceChannelId: source.channelId),
        child: const Text('Open source message'),
      ),
    ))));
    await tester.tap(find.text('Open source message'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Copy message link'));
    await tester.pumpAndSettle();
    expect(copied, 'vocle://c/source-channel/m/source-message');
    expect(Uri.parse(copied!).scheme, 'vocle');
    expect(Uri.parse(copied!).host, 'c');
    expect(Uri.parse(copied!).pathSegments,
        ['source-channel', 'm', 'source-message']);
    expect(find.text('Forward message'), findsNothing);
    // Q13 remains open: there is no verified app route for this copied URI.
  });
}

  testWidgets('FR-LINK-03: push routes debounce, queue through auth and recover missing target',
      (tester) async {
    FlutterSecureStorage.setMockInitialValues({});
    SharedPreferences.setMockInitialValues({});
    final deps = AppDependencies.instance;
    deps.init();
    final adapter = _PushApiAdapter();
    deps.apiClient.dio.httpClientAdapter = adapter;
    final router = deps.appRouter.router;
    addTearDown(router.dispose);

    const channel = PushPayload(type: 'message', spaceId: 'space-synthetic',
        channelId: 'channel-synthetic');
    const dm = PushPayload(type: 'message', channelId: 'dm-synthetic');
    const handoff = PushPayload(type: 'handoff', spaceId: 'space-synthetic',
        handoffId: 'handoff-synthetic');
    const missing = PushPayload(type: 'handoff', spaceId: 'space-synthetic',
        handoffId: 'handoff-missing');

    expect(deps.authBloc.state.status, AuthStatus.unknown);
    PushNotificationRouter.open(channel);
    PushNotificationRouter.open(dm);
    PushNotificationRouter.open(handoff);
    await tester.pump();
    // No push target should open before a synthetic session is restored.
    expect(router.routeInformationProvider.value.uri.path,
        isNot(AppRoutes.spaceHandoffDetailPath('space-synthetic', 'handoff-synthetic')));
    await deps.secureStorage.saveSession(accessToken: '[REDACTED]',
        refreshToken: '[REDACTED]', userId: 'doctor-synthetic');
    await tester.pumpWidget(MultiBlocProvider(providers: [
      BlocProvider<AuthBloc>.value(value: deps.authBloc),
      BlocProvider<NavBadgesCubit>.value(value: deps.navBadgesCubit),
      BlocProvider<NotificationBadgeCubit>.value(
          value: deps.notificationBadgeCubit),
    ], child: MaterialApp.router(routerConfig: router)));
    await tester.pump();

    for (var i = 0; i < 20 &&
        deps.authBloc.state.status != AuthStatus.authenticated; i++) {
      await tester.pump(const Duration(milliseconds: 20));
    }
    expect(deps.authBloc.state.status, AuthStatus.authenticated);
    expect(deps.authBloc.state.user?.id, 'doctor-synthetic');
    expect(adapter.paths, contains('/api/users/me'));
    expect(router.routeInformationProvider.value.uri.path,
        AppRoutes.spaceHandoffDetailPath('space-synthetic', 'handoff-synthetic'));

    PushNotificationRouter.open(channel);
    PushNotificationRouter.open(dm);
    PushNotificationRouter.open(handoff);
    await tester.pump(const Duration(milliseconds: 230));
    expect(router.routeInformationProvider.value.uri.path,
        AppRoutes.spaceHandoffDetailPath('space-synthetic', 'handoff-synthetic'));

    await tester.pumpAndSettle();

    // A stale target must fall back to a stable list, rather than strand the user.
    PushNotificationRouter.open(missing);
    await tester.pump(const Duration(milliseconds: 230));
    await tester.pumpAndSettle();
    expect(router.state.uri.path,
        AppRoutes.spaceHandoffDetailPath('space-synthetic', 'handoff-missing'));
    expect(adapter.paths, contains('/api/handoffs/handoff-missing'));
    expect(find.text('Resource not found'), findsOneWidget);
    expect(router.routeInformationProvider.value.uri.path,
        AppRoutes.handoffs);
  });
}

testWidgets('FR-NAV-01: launch routes from stored session and profile',
    (tester) async {
  FlutterSecureStorage.setMockInitialValues({});
  SharedPreferences.setMockInitialValues({});
  final deps = AppDependencies.instance;
  deps.init();
  final adapter = _LoopbackAdapter();
  deps.apiClient.dio.httpClientAdapter = adapter;
  final observed = <String, List<String>>{};
  final frameworkErrors = <String>[];
  void captureFrameworkError() {
    final error = tester.takeException();
    if (error != null) frameworkErrors.add(error.toString());
  }

  Future<void> scenario(String label, bool hasSession, UserModel user,
      AuthStatus expectedStatus, String expectedPath) async {
    final socket = FakeSocketClient();
    final session = _LaunchSession(present: hasSession, socket: socket);
    final profiles = _LaunchProfiles(user);
    final auth = AuthBloc(authRepository: session, userRepository: profiles);
    addTearDown(() async {
      await auth.close();
      await socket.disposeFake();
    });
    final appRouter = AppRouter(authBloc: auth);
    final router = appRouter.router;
    final locations = <String>[];
    void recordLocation() {
      locations.add(router.routeInformationProvider.value.uri.path);
    }
    router.routeInformationProvider.addListener(recordLocation);
    await tester.pumpWidget(MultiBlocProvider(providers: [
      BlocProvider<AuthBloc>.value(value: auth),
      BlocProvider<NavBadgesCubit>.value(value: deps.navBadgesCubit),
      BlocProvider<NotificationBadgeCubit>.value(
          value: deps.notificationBadgeCubit),
    ], child: MaterialApp.router(routerConfig: router)));
    captureFrameworkError();
    await tester.pump();
    captureFrameworkError();
    await tester.pump(const Duration(milliseconds: 20));
    captureFrameworkError();
    await tester.pump(const Duration(milliseconds: 20));
    captureFrameworkError();
    expect(auth.state.status, expectedStatus, reason: label);
    expect(router.routeInformationProvider.value.uri.path,
        expectedPath, reason: label);
