    const dms = await request('/api/channels/dm', { token: [REDACTED] });
    assert.ok(!dms.data.channels.some((channel) => channel.members?.some((member) => member._id === a.userId)));
    const retry = await request(`/api/message-requests/${id}/accept`, { method: 'POST', token: [REDACTED], expectedStatus: 400 });
